package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.media.AudioManager;import android.net.Uri;import android.os.*;import android.speech.tts.*;import java.util.*;import java.util.concurrent.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,shadows={SpeechServiceTest.ManualTts.class}) @LooperMode(LooperMode.Mode.PAUSED)
public class SpeechHeadingTest {
 ServiceController<ReadAloudService> controller;ReadAloudService service;
 @Before public void setup(){Application app=RuntimeEnvironment.getApplication();ShadowTextToSpeech.addVoice(new Voice("pt-local",new Locale("pt","PT"),400,200,false,Collections.emptySet()));new SpeechProfile("com.google.android.tts","pt-local","pt",false,1).save(app.getSharedPreferences("seeky",0));SpeechServiceTest.ManualTts.queues.clear();SpeechServiceTest.ManualTts.texts.clear();SpeechServiceTest.ManualTts.silences.clear();SpeechServiceTest.ManualTts.gapIds.clear();SpeechServiceTest.ManualTts.silentFails=false;controller=Robolectric.buildService(ReadAloudService.class).create();service=controller.get();shadowOf(service.audio).setNextFocusRequestResponse(AudioManager.AUDIOFOCUS_REQUEST_GRANTED);}
 void start(String text)throws Exception{service.onStartCommand(new Intent().setAction(ReadAloudService.START).setDataAndType(Uri.parse("content://seeky.heading/book.txt"),"text/plain").putExtra("selection",text),0,1);drain();SpeechServiceTest.ready(service);}
 void drain()throws Exception{service.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}
 @After public void close(){controller.destroy();SpeechServiceTest.ManualTts.silentFails=false;}
 @Test public void titleAndBodyAreSeparatedByQueuedTwoSecondSilence()throws Exception{start("Título isolado\n\nUma frase de conteúdo com pontuação.");assertEquals("Título isolado",SpeechServiceTest.ManualTts.texts.get(0));assertEquals("Uma frase de conteúdo com pontuação.",SpeechServiceTest.ManualTts.texts.get(1));assertEquals(Arrays.asList(2000L),SpeechServiceTest.ManualTts.silences);String first=service.cursor.pending.id,gap=SpeechServiceTest.ManualTts.gapIds.get(0),body=service.cursor.queued.id;service.progress.onDone(first);service.progress.onStart(gap);shadowOf(Looper.getMainLooper()).idle();assertTrue(service.message.contains("Pausa após título"));assertEquals(body,service.cursor.pending.id);service.progress.onDone(gap);service.progress.onStart(body);shadowOf(Looper.getMainLooper()).idle();assertEquals("A ler em voz alta",service.message);assertEquals(2,SpeechServiceTest.ManualTts.texts.size());}
 @Test public void finalTitleDoesNotFinishOrAdvanceBeforeTheSilenceCompletes()throws Exception{start("Título isolado");String id=service.cursor.pending.id,gap=SpeechServiceTest.ManualTts.gapIds.get(0);service.progress.onDone(id);shadowOf(Looper.getMainLooper()).idle();assertNotNull(service.request);assertEquals(gap,service.waitingGap);service.progress.onDone(gap);shadowOf(Looper.getMainLooper()).idle();assertNull(service.request);}
 @Test public void pauseDuringTitleGapCancelsQueuedBodyAndResumesAtItsStart()throws Exception{String text="Título isolado\n\nUma frase de conteúdo com pontuação.";start(text);String title=service.cursor.pending.id,gap=SpeechServiceTest.ManualTts.gapIds.get(0),oldBody=service.cursor.queued.id;service.progress.onDone(title);shadowOf(Looper.getMainLooper()).idle();service.pause("Pausado");service.progress.onDone(gap);service.progress.onDone(oldBody);shadowOf(Looper.getMainLooper()).idle();assertTrue(service.cursor.paused);service.resume();assertEquals(text.indexOf("Uma frase"),service.cursor.pending.start);assertEquals("Uma frase de conteúdo com pontuação.",SpeechServiceTest.ManualTts.texts.get(SpeechServiceTest.ManualTts.texts.size()-1));}
 @Test public void unsupportedSilentQueueFallsBackToCancellableTwoSecondDelay()throws Exception{SpeechServiceTest.ManualTts.silentFails=true;start("Título isolado\n\nUma frase de conteúdo com pontuação.");assertEquals(1,SpeechServiceTest.ManualTts.texts.size());service.progress.onDone(service.cursor.pending.id);shadowOf(Looper.getMainLooper()).idle();shadowOf(Looper.getMainLooper()).idleFor(1999,TimeUnit.MILLISECONDS);assertEquals(1,SpeechServiceTest.ManualTts.texts.size());shadowOf(Looper.getMainLooper()).idleFor(1,TimeUnit.MILLISECONDS);assertEquals(2,SpeechServiceTest.ManualTts.texts.size());assertTrue(service.cursor.pending.text.contains("Uma frase"));}
 @Test public void timeSkipsKeepPauseStateAndRejectStaleCallbacks()throws Exception{StringBuilder text=new StringBuilder();for(int i=0;i<200;i++)text.append("Uma frase de leitura para navegar no documento. ");start(text.toString());String old=service.cursor.pending.id;service.pause("Pausado");service.seekSeconds(20);drain();assertTrue(service.cursor.paused);int ahead=service.cursor.offset;assertTrue(ahead>0);service.progress.onDone(old);shadowOf(Looper.getMainLooper()).idle();assertEquals(ahead,service.cursor.offset);service.seekSeconds(-10);drain();assertTrue(service.cursor.offset<ahead);assertTrue(service.cursor.paused);int at=service.cursor.offset;service.onStartCommand(new Intent().setAction(ReadAloudService.FORWARD).putExtra("token","stale"),0,2);drain();assertEquals(at,service.cursor.offset);} @Test public void pauseCancelsAnOutstandingSeekWithoutRestartingSpeech()throws Exception{StringBuilder text=new StringBuilder();for(int i=0;i<200;i++)text.append("Uma frase de leitura para navegar no documento. ");start(text.toString());CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);service.worker.execute(()->{entered.countDown();try{release.await(10,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(entered.await(10,TimeUnit.SECONDS));int before=service.cursor.spoken,count=SpeechServiceTest.ManualTts.texts.size();service.seekSeconds(20);assertTrue(service.seeking);service.pause("Pausado");release.countDown();drain();assertFalse(service.seeking);assertFalse(service.loading);assertTrue(service.cursor.paused);assertEquals(before,service.cursor.offset);assertEquals(count,SpeechServiceTest.ManualTts.texts.size());}

}
